def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    # Process each column
    for c in range(cols):
        # Find foreground cells above last row (in order from bottom to top)
        fg_list = []
        for r in range(rows - 1, 0, -1):
            if grid[r][c] == 3:
                fg_list.append(r)

        # Convert EXCEPT the bottom 2 foreground cells in each column
        for r in reversed(fg_list):
            if len(fg_list) > 2:
                output[r][c] = 2
            # else: keep as 3 (not enough foreground cells or in bottom 2)

    # Last row is handled by the above loop (it's rows-1, but we stop at rows-2)
    # So process last row separately
    for c in range(cols):
        if grid[rows - 1][c] == 3:
            output[rows - 1][c] = 2

    return output
